import numpy as np

def lower_median(values):
    sorted_values = np.sort(values)
    median_index = len(sorted_values) // 2
    if len(sorted_values) % 2 == 0:
        return sorted_values[median_index - 1]
    else:
        return sorted_values[median_index]
```

