def month_ends(start, n):
    from pandas import date_range

    start_date = pd.to_datetime(start)
    if start_date.day != 1:
        start_date = start_date.replace(day=1) + pd.offsets.MonthEnd()
    return date_range(start=start_date, periods=n, freq="ME")
