def month_ends(start, n):
    from pandas import date_range, DatetimeIndex

    start_date = pd.to_datetime(start)
    if start_date.day != 1:
        start_date = start_date.replace(day=1)
        if start_date.month == 12:
            start_date = start_date.replace(month=1, year=start_date.year + 1)
        else:
            start_date = start_date.replace(month=start_date.month + 1)

    periods = date_range(start=start_date, periods=n + 1, freq="M")[1:]
    return periods[periods.is_month_end]
```

