def fill_forward(df):
    import pandas as pd

    df_copy = df.copy()
    for col in df_copy.columns:
        prev_value = None
        for i in range(len(df_copy)):
            if pd.isna(df_copy.loc[i, col]):
                if prev_value is not None:
                    df_copy.loc[i, col] = prev_value
            else:
                prev_value = df_copy.loc[i, col]
    return df_copy
```

