def fill_forward(df):
    result = df.copy()
    for col in df.columns:
        last_val = None
        for i, value in enumerate(df[col]):
            if pd.isna(value):
                if last_val is not None:
                    result.iloc[i, df.columns.get_loc(col)] = last_val
            else:
                last_val = value
    return result
