def fill_forward(df):
    # Create a copy of the DataFrame to avoid modifying the original
    df_copy = df.copy()

    # Iterate over each column
    for col in df_copy.columns:
        # Get the last valid index of the column
        last_valid_idx = df_copy[col].last_valid_index()

        # Iterate over the DataFrame row by row
        for idx, value in df_copy[col].items():
            # If the value is NaN, replace it with the last valid value in the column
            if pd.isna(value):
                if last_valid_idx is not None and last_valid_idx >= idx:
                    df_copy.at[idx, col] = df_copy.at[last_valid_idx, col]

    return df_copy
```

