from django.db import models

def make_sku(code: str):
    class SKU(models.Model):
        code = models.CharField(max_length=7, unique=True, help_text="SKU code must match ^[A-Z]{3}-\d{4}$")

    if not code.match(r"^[A-Z]{3}-\d{4}$"):
        raise ValueError("Code does not match the required pattern ^[A-Z]{3}-\d{4}$")

    return SKU(code=code)
