from pydantic import BaseModel, root_validator


def make_sku(code: str):
    class Sku(BaseModel):
        code: str

        @root_validator
        def validate_code(cls, values):
            if not values['code'].startswith('ABC') or not values['code'][4:].isdigit() or len(values['code']) != 7:
                raise ValueError(f"Invalid SKU code: {values['code']}")
            return values

    try:
        return Sku(code=code)
    except ValueError as e:
        raise ValueError(f"Invalid SKU code: {e}")
