from pydantic import BaseModel, root_validator

class RangeModel(BaseModel):
    lo: int
    hi: int

    @root_validator(pre=True)
    def check_hi_lo(cls, values):
        lo = values.get('lo')
        hi = values.get('hi')
        if hi is not None and lo is not None and hi < lo:
