from django.db import models
import re

class SKU(models.Model):
    code = models.CharField(
        max_length=8,
        unique=True,
        validators=[models.RegexValidator(regex=r'^[A-Z]{3}-\d{4}$', message='Code must be in the format ABC-1234')]
    )

def make_sku(code: str):
    return SKU.objects.create(code=code)
```

